# acme-gateway sample build inputs

The local adapter explicitly maps the requested /:/host source to /srv/fake_host, never the machine host root. The normal generator /opt/gen.sh runs real grpc_tools.protoc, and synchronizes the complete public examples/host-files.json manifest. The mapped SSH file contains a host public key in known_hosts format, not an authorized user key. make verify exercises message serialization and service descriptors.
-- protos --
syntax = "proto3";

package acme.gateway.common;

message Timestamp {
  int64 seconds = 1;
  int32 nanos = 2;
}

message Error {
  int32 code = 1;
  string message = 2;
}
syntax = "proto3";

package acme.gateway.v1;

import "common.proto";

message RouteRequest {
  string route_id = 1;
  bytes payload = 2;
  acme.gateway.common.Timestamp sent_at = 3;
}

message RouteReply {
  bool accepted = 1;
  acme.gateway.common.Error error = 2;
}

service Gateway {
  rpc Route(RouteRequest) returns (RouteReply);
}
-- verifier --
import sys
sys.path.insert(0,'gen')
import common_pb2,gateway_pb2
t=common_pb2.Timestamp(seconds=1700000000,nanos=321)
r=gateway_pb2.RouteRequest(route_id='sample',payload=b'hello',sent_at=t)
assert gateway_pb2.RouteRequest.FromString(r.SerializeToString())==r
reply=gateway_pb2.RouteReply(accepted=True,error=common_pb2.Error(code=0,message='ok'))
assert gateway_pb2.RouteReply.FromString(reply.SerializeToString()).accepted
assert gateway_pb2.DESCRIPTOR.services_by_name['Gateway'].methods_by_name['Route'].input_type.full_name=='acme.gateway.v1.RouteRequest'
print('protobuf verification passed')
